    font-family: 'RevueWatermark';
    src: url(data:font/truetype;charset=utf-8;base64,) format('truetype');
}

.watermark-shared {
    position: fixed; 
    top: 35%; 
    left: 50%; 
    transform: translate(-50%, -50%);
